"use strict";(self.webpackChunkrains_blog=self.webpackChunkrains_blog||[]).push([["607"],{7735(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"still-here-btw","metadata":{"permalink":"/blog/still-here-btw","source":"@site/blog/2026-05-30-still-here-btw/index.mdx","title":"Still Here, BTW","description":"Hello, Dear Reader.","date":"2026-05-30T00:00:00.000Z","tags":[{"inline":false,"label":"Campaign","permalink":"/blog/tags/campaign"}],"readingTime":1.72,"hasTruncateMarker":true,"authors":[{"name":"Rain","title":"she/her","url":"https://github.com/rainyy012","page":{"permalink":"/blog/authors/rain"},"socials":{"bluesky":"https://bsky.app/profile/rainyy012.bsky.social","email":"mailto:rainyy-012@proton.me"},"imageURL":"https://github.com/rainyy012.png","key":"rain"}],"frontMatter":{"slug":"still-here-btw","title":"Still Here, BTW","authors":["rain"],"tags":["campaign"]},"unlisted":false},"content":"import { YTEmbed } from \'@site/src/components/yt-embed\'\\n\\n\\n## Hello, Dear Reader.\\n\\nThank you for being here.\\n\\nThis marks the first chapter of Rain\'s Blog, with more content coming in the future.\\n\\nThis idea started a few months ago, but it wasn\'t until last month that the whole picture became clear to me. Since Pride Month is just around the corner, there is no better opportunity to commemorate it by starting my new blog, I thought.\\n\\n{/* truncate */}\\n\\n## Now, Onto The Main Topic:\\n\\n[#StillHereBTW](https://bsky.app/search?q=%23stillherebtw) was inspired by Shyaren\'s video titled \\"[My MOST Important Video](https://www.youtube.com/watch?v=aCz_PulxZVI)\\". In case you haven\'t heard of her or watched the video before, I highly recommend you to check it out:\\n\\n<YTEmbed videoId=\'aCz_PulxZVI\' />\\n<br />\\n\\n<br /><br />\\n\\nTo expand on this topic, here\'s my take: We need our presence to be acknowledged and our voices to be heard\u2026 so that we can be treated with compassion just as any decent human being would to one another. \u{1F644}\\n\\nIt\'s infuriating that decency is something we need to demand for. Unfortunately, there are still many people who consciously choose to be hostile towards the queer community.\\n\\nThey deny us and want us gone. This has been the case in the past, still is in the present, and will be for the foreseeable future. Now, as much as I hate to say, definitively, I don\'t know if there is hope or not. I can\'t tell if what I\'m clinging onto so desperately is actually hope or delusion, but in spite of so many efforts to get rid of us, we\'re still here, and perhaps that in itself is a form of hope\u2026 and perhaps, in the face of adversity, simply being here is the least effort we could put in to form resistance.\\n\\n<br />\\n\\nWith that said,\\n\\n## Thank You For Reading\\n\\nI will write to you again soon. Until then, please stay vigilant and be safe.\\n\\n<br />From the bottom of my heart,<br />\\n<span style={{\\n  fontFamily: \'\\"Fleur De Leah\\", cursive\',\\n  fontSize: \'28pt\',\\n}}>Rain</span>\\n\\n<br />"}]}}')}}]);